from pathlib import Path
import json

PAGE=Path('my-meta/index.html')
LIVE=Path('data/live-meta.json')
if not PAGE.exists() or not LIVE.exists():
    raise RuntimeError('My Meta and live roster are required for local data portability')
page=PAGE.read_text(encoding='utf-8')
if 'id="localDataPortability"' in page:
    print('Local data portability already injected')
    raise SystemExit(0)
heroes=[h.get('name') for h in json.loads(LIVE.read_text(encoding='utf-8')).get('heroes',[]) if h.get('name')]
if len(heroes)!=133:
    raise RuntimeError(f'Expected 133 live heroes for portability validation, got {len(heroes)}')
payload=json.dumps(heroes,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
CSS='''<style id="local-data-portability-style">.local-port{margin-top:18px;padding:18px;border:1px solid #2a3d58;border-radius:20px;background:#0a1321}.local-port-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap}.local-port h2{margin:3px 0 5px}.local-port p{color:#8294ad;font-size:10px;line-height:1.55}.local-port-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:13px}.local-port button,.local-port label{display:inline-flex;align-items:center;justify-content:center;min-height:38px;padding:9px 12px;border:1px solid #30445f;border-radius:11px;background:#0e1929;color:#d8e5f6;font:850 10px/1 system-ui;cursor:pointer}.local-port button:hover,.local-port label:hover,.local-port button:focus-visible,.local-port label:focus-within{outline:none;border-color:#54e5ff}.local-port .danger{color:#ffabaf;border-color:#613d48}.local-port input[type=file]{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}.local-port-status{margin:10px 0 0;color:#8b9db8;font-size:10px}.local-port-status.ok{color:#7ce9bf}.local-port-status.warn{color:#ffd27c}</style>'''
PANEL='''<section id="localDataPortability" class="local-port"><div class="local-port-head"><div><small>DATOS LOCALES</small><h2>Respaldo y portabilidad</h2><p>Exporta Watchlist, perfil, drafts y comparaciones recientes a un JSON. La importación valida el archivo antes de reemplazar esas preferencias en este navegador.</p></div></div><div class="local-port-actions"><button id="exportLocalData" type="button">Exportar respaldo</button><label for="importLocalData">Importar respaldo<input id="importLocalData" type="file" accept="application/json,.json"></label><button id="clearLocalData" class="danger" type="button">Borrar datos locales</button></div><p id="localDataStatus" class="local-port-status" aria-live="polite">El archivo se procesa localmente y no se sube a Meta Forge.</p></section>'''
marker='</main>'
if marker not in page: raise RuntimeError('My Meta main closing marker missing')
page=page.replace(marker,PANEL+marker,1)
JS=f'''<script id="local-data-portability-script">(()=>{{const HEROES=new Set({payload}),KEYS=['mf_watchlist_v1','mf_profile_v1','mf_draft_history_v1','mf_turn_draft_history_v1','mf_compare_recent_v1'],exportBtn=document.getElementById('exportLocalData'),importInput=document.getElementById('importLocalData'),clearBtn=document.getElementById('clearLocalData'),status=document.getElementById('localDataStatus');if(!exportBtn||!importInput||!clearBtn||!status)return;const roles=new Set(['Jungle','EXP','Mid','Gold','Roam']);function msg(t,k=''){{status.textContent=t;status.className='local-port-status'+(k?' '+k:'')}}function parse(k,f=null){{try{{const v=localStorage.getItem(k);return v===null?f:JSON.parse(v)}}catch{{return f}}}}function names(v,max){{return [...new Set((Array.isArray(v)?v:[]).filter(x=>typeof x==='string'&&HEROES.has(x)))].slice(0,max)}}function sanitizeProfile(v){{if(!v||typeof v!=='object'||Array.isArray(v))return null;if(v.skipped)return {{skipped:true,updatedAt:Number(v.updatedAt)||Date.now()}};const role=roles.has(v.role)?v.role:null,hs=names(v.heroes,5);return role?{{role,heroes:hs,updatedAt:Number(v.updatedAt)||Date.now()}}:null}}function sanitizeFree(v){{return (Array.isArray(v)?v:[]).slice(0,8).map(d=>({{allies:names(d?.allies,5),enemies:names(d?.enemies,5),ts:Number(d?.ts)||Date.now()}}))}}function sanitizeTurn(v){{return (Array.isArray(v)?v:[]).slice(0,8).map(d=>{{const first=d?.first==='red'?'red':'blue',history=(Array.isArray(d?.history)?d.history:[]).slice(0,20).filter(x=>x&&HEROES.has(typeof x==='string'?x:x.hero)).map(x=>typeof x==='string'?x:{{side:x.side==='red'?'red':'blue',type:x.type==='ban'?'ban':'pick',slot:Math.max(1,Math.min(5,Number(x.slot)||1)),hero:x.hero}});return {{first,history,ts:Number(d?.ts)||Date.now(),patch:typeof d?.patch==='string'?d.patch:''}}}})}}function sanitizeRecent(v){{const seen=new Set(),out=[];for(const r of Array.isArray(v)?v:[]){{if(out.length>=6)break;const a=r?.a,b=r?.b;if(!HEROES.has(a)||!HEROES.has(b)||a===b)continue;const key=[a,b].sort((x,y)=>x.localeCompare(y)).join(':::');if(seen.has(key))continue;seen.add(key);out.push({{a,b,key,ts:Number(r?.ts)||Date.now()}})}}return out}}function sanitized(data){{return {{mf_watchlist_v1:names(data?.mf_watchlist_v1,133),mf_profile_v1:sanitizeProfile(data?.mf_profile_v1),mf_draft_history_v1:sanitizeFree(data?.mf_draft_history_v1),mf_turn_draft_history_v1:sanitizeTurn(data?.mf_turn_draft_history_v1),mf_compare_recent_v1:sanitizeRecent(data?.mf_compare_recent_v1)}}}}exportBtn.addEventListener('click',()=>{{const raw={{}};KEYS.forEach(k=>raw[k]=parse(k,null));const backup={{app:'MLBB Meta Forge',version:1,exported_at:new Date().toISOString(),data:sanitized(raw)}},blob=new Blob([JSON.stringify(backup,null,2)],{{type:'application/json;charset=utf-8'}}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='meta-forge-backup.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),0);msg('Respaldo exportado. Contiene solo datos locales de Meta Forge.','ok')}});importInput.addEventListener('change',async()=>{{const file=importInput.files?.[0];importInput.value='';if(!file)return;if(file.size>1024*1024){{msg('El respaldo supera 1 MB y fue rechazado.','warn');return}}try{{const backup=JSON.parse(await file.text());if(backup?.app!=='MLBB Meta Forge'||backup?.version!==1||!backup?.data)throw new Error('schema');const clean=sanitized(backup.data);if(!confirm('Importar reemplazará Watchlist, perfil, drafts e historial reciente en este navegador. ¿Continuar?'))return;for(const k of KEYS){{const value=clean[k];if(value===null)localStorage.removeItem(k);else localStorage.setItem(k,JSON.stringify(value))}}msg('Respaldo importado y validado. Recargando Mi Meta…','ok');setTimeout(()=>location.reload(),450)}}catch{{msg('No pudimos importar: el archivo no tiene un formato de respaldo válido.','warn')}}}});clearBtn.addEventListener('click',()=>{{if(!confirm('¿Borrar Watchlist, perfil, drafts y comparaciones recientes de este navegador?'))return;KEYS.forEach(k=>localStorage.removeItem(k));msg('Datos locales borrados. Recargando…','ok');setTimeout(()=>location.reload(),350)}}) }})();</script>'''
page=page.replace('</head>',CSS+'</head>',1)
page=page.replace('</body>',JS+'</body>',1)
PAGE.write_text(page,encoding='utf-8')
print(f'Injected local data portability into My Meta: heroes={len(heroes)}; keys=5; backup_version=1')
